// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title DeviceRegistry
 * @notice This contract manages device registration and update information.
 *         Each device is identified by a unique deviceId (e.g., serial number or MAC address)
 *         and associated with its owner, firmware version, and the last update timestamp.
 */
contract DeviceRegistry {

    // Struct to store device information.
    struct DeviceInfo {
        address owner;            // The Ethereum address that owns/registered the device.
        string deviceId;          // Unique identifier for the device.
        string firmwareVersion;   // Current firmware version of the device.
        uint256 lastUpdated;      // Timestamp of the last firmware update.
    }

    // Mapping from deviceId to DeviceInfo.
    mapping(string => DeviceInfo) public devices;

    // Event emitted when a device is registered.
    event DeviceRegistered(
        string indexed deviceId,
        address indexed owner,
        string firmwareVersion,
        uint256 timestamp
    );

    // Event emitted when a device's firmware is updated.
    event DeviceUpdated(
        string indexed deviceId,
        string newFirmwareVersion,
        uint256 timestamp
    );

    /**
     * @notice Registers a new device.
     * @param _deviceId Unique identifier for the device (e.g., serial number).
     * @param _firmwareVersion The initial firmware version.
     */
    function registerDevice(
        string calldata _deviceId,
        string calldata _firmwareVersion
    ) external {
        require(bytes(_deviceId).length > 0, "Device ID is required");
        require(devices[_deviceId].lastUpdated == 0, "Device already registered");

        devices[_deviceId] = DeviceInfo({
            owner: msg.sender,
            deviceId: _deviceId,
            firmwareVersion: _firmwareVersion,
            lastUpdated: block.timestamp
        });

        emit DeviceRegistered(_deviceId, msg.sender, _firmwareVersion, block.timestamp);
    }

    /**
     * @notice Updates the firmware version for a registered device.
     * @param _deviceId The unique identifier of the device.
     * @param _newFirmwareVersion The new firmware version.
     */
    function updateDeviceFirmware(
        string calldata _deviceId,
        string calldata _newFirmwareVersion
    ) external {
        DeviceInfo storage device = devices[_deviceId];
        require(device.lastUpdated != 0, "Device not registered");
        require(device.owner == msg.sender, "Only the device owner can update firmware");

        device.firmwareVersion = _newFirmwareVersion;
        device.lastUpdated = block.timestamp;

        emit DeviceUpdated(_deviceId, _newFirmwareVersion, block.timestamp);
    }

    /**
     * @notice Retrieves device information by deviceId.
     * @param _deviceId The unique identifier of the device.
     * @return owner The device owner address.
     * @return deviceId The unique identifier.
     * @return firmwareVersion The current firmware version.
     * @return lastUpdated The last update timestamp.
     */
    function getDeviceInfo(string calldata _deviceId)
        external
        view
        returns (
            address owner,
            string memory deviceId,
            string memory firmwareVersion,
            uint256 lastUpdated
        )
    {
        DeviceInfo memory device = devices[_deviceId];
        require(device.lastUpdated != 0, "Device not registered");
        return (device.owner, device.deviceId, device.firmwareVersion, device.lastUpdated);
    }
}

